const MAX_CHUNK = 3800;
const LABEL_PREFIX = 'Daily Advisor';
const LABEL_RESERVE = 30; // headroom for "Daily Advisor (i/N)\n\n" so label + chunk never exceeds MAX_CHUNK
const SPLIT_BUDGET = MAX_CHUNK - LABEL_RESERVE;

const input = $input.first().json;
const text = input.data;

if (typeof text !== 'string' || text.trim().length === 0) {
  throw new Error('GitHub response did not contain the expected raw markdown body (data field missing or empty).');
}

function splitIntoChunks(source, maxLen) {
  const chunks = [];
  let current = '';

  function flush() {
    if (current.length > 0) {
      chunks.push(current);
      current = '';
    }
  }

  function addPiece(piece, separator) {
    const candidate = current.length === 0 ? piece : current + separator + piece;
    if (candidate.length <= maxLen) {
      current = candidate;
      return;
    }
    flush();
    if (piece.length <= maxLen) {
      current = piece;
      return;
    }
    const lines = piece.split('\n');
    if (lines.length > 1) {
      for (const line of lines) {
        addPiece(line, '\n');
      }
      return;
    }
    let rest = piece;
    while (rest.length > maxLen) {
      chunks.push(rest.slice(0, maxLen));
      rest = rest.slice(maxLen);
    }
    current = rest;
  }

  const paragraphs = source.split('\n\n');
  for (const paragraph of paragraphs) {
    addPiece(paragraph, '\n\n');
  }
  flush();
  return chunks;
}

const chunks = splitIntoChunks(text, SPLIT_BUDGET);

return chunks.map((chunk, i) => {
  const label = chunks.length > 1 ? (LABEL_PREFIX + ' (' + (i + 1) + '/' + chunks.length + ')\n\n') : '';
  return { json: { text: label + chunk, chunkIndex: i + 1, chunkCount: chunks.length } };
});

_setup_notes:
'Prepare Telegram message chunks' (Code node) reads only $json.data (the raw markdown body) from the GitHub node, splits it into chunks under 3800 characters (conservative margin under Telegram's 4096 hard limit), preferring paragraph boundaries (

), falling back to line boundaries (
), and only hard-splitting mid-line as a last resort for a single line longer than the limit. Emits one item per chunk. Both Telegram nodes below run off this SAME output in parallel, so both recipients get every chunk, independently, in order (n8n runs each Telegram node once per input item by default, preserving order) -- a failure sending to one recipient does not block or skip the other. A 'Daily Advisor (i/N)' label is prepended only when there's more than one chunk -- a single short briefing gets no label at all.
